const targetSignals = new Set($('Configure Target Accounts & Signals').first()?.json?.targetSignals || []);
const hiringByDomain = {};
const qualifiedDomains = [];

for (const item of $input.all()) {
  const row = item.json;
  if (!row || row.status !== 'hiring' || !row.domain) continue;
  const signals = Array.isArray(row.hiringIntentSignals) ? row.hiringIntentSignals : [];
  const matches = targetSignals.size === 0 ? signals : signals.filter((s) => targetSignals.has(s));
  if (matches.length === 0) continue;

  const key = String(row.domain).toLowerCase().trim();
  if (hiringByDomain[key]) continue;
  hiringByDomain[key] = {
    domain: key,
    atsProvider: row.atsProvider,
    careersUrl: row.careersUrl,
    openRolesCount: row.openRolesCount ?? 0,
    matchedSignals: matches,
    allSignals: signals,
    techStackFromJobs: (row.techStackFromJobs || []).slice(0, 10),
    postedLast14Days: row.velocity?.postedLast14Days ?? 0,
    sampleRoles: (row.jobs || []).slice(0, 3).map((j) => j.title)
  };
  qualifiedDomains.push(key);
}

if (qualifiedDomains.length === 0) return [];

return [{
  json: {
    domains: qualifiedDomains,
    qualifiedCount: qualifiedDomains.length,
    hiringByDomain
  }
}];

const hiringByDomain = $('Filter Accounts Matching Hiring Intent').first()?.json?.hiringByDomain || {};
const output = [];

for (const item of $input.all()) {
  const lead = item.json;
  if (!lead || lead.status !== 'enriched' || !lead.domain) continue;
  const key = String(lead.domain).toLowerCase().trim();
  const hiring = hiringByDomain[key] || {};

  const verifiedDms = Array.isArray(lead.decisionMakers)
    ? lead.decisionMakers.filter((dm) => dm && dm.verifiedForBilling === true && dm.email)
    : [];

  const base = {
    domain: key,
    companyName: lead.companyName || key,
    atsProvider: hiring.atsProvider || null,
    careersUrl: hiring.careersUrl || null,
    openRolesCount: hiring.openRolesCount ?? 0,
    postedLast14Days: hiring.postedLast14Days ?? 0,
    matchedSignals: (hiring.matchedSignals || []).join(', '),
    internalTechFromJobs: (hiring.techStackFromJobs || []).join(', '),
    sampleOpenRoles: (hiring.sampleRoles || []).join(' | '),
    emailProvider: lead.dns?.emailProvider || null,
    hasMx: lead.dns?.hasMx ?? false,
    companyLinkedin: lead.socials?.linkedin || null
  };

  if (verifiedDms.length > 0) {
    for (const dm of verifiedDms) {
      output.push({
        json: {
          ...base,
          contactType: 'verified_decision_maker',
          contactName: dm.fullName,
          contactRole: dm.role,
          contactEmail: dm.email,
          sourceUrl: dm.sourceUrl || lead.sourceUrl || null
        }
      });
    }
  } else if (lead.primaryEmail) {
    output.push({
      json: {
        ...base,
        contactType: 'company_primary_email',
        contactName: null,
        contactRole: null,
        contactEmail: lead.primaryEmail,
        sourceUrl: lead.sourceUrl || null
      }
    });
  }
}

return output;
